/**
 * Translation for the workbench.
 *
 * German is the source language and stays inline in the components; a key that
 * has no entry here falls back to the text it was called with. That way
 * translating a surface is additive and never leaves a blank label behind.
 *
 * The languages added after English fall through English on the way to that
 * German source, because a gap should show a reader something they can more
 * likely read rather than the source language by accident.
 */

export type Locale =
  | "de" | "en" | "fr" | "es" | "ru"
  | "pl" | "tr" | "pt" | "hu" | "it" | "nl";

/**
 * The languages on offer, each named in its own words.
 *
 * A Polish speaker looks for Polski in the list, not for Polnisch or Polish,
 * so the label is never translated — it is the one string that must read the
 * same whatever language the interface happens to be in.
 */
export const locales: Array<{ id: Locale; label: string }> = [
  { id: "de", label: "Deutsch" },
  { id: "en", label: "English" },
  { id: "fr", label: "Français" },
  { id: "es", label: "Español" },
  { id: "it", label: "Italiano" },
  { id: "nl", label: "Nederlands" },
  { id: "pl", label: "Polski" },
  { id: "pt", label: "Português" },
  { id: "hu", label: "Magyar" },
  { id: "tr", label: "Türkçe" },
  { id: "ru", label: "Русский" },
];

