  // The explanation under each settings heading.
  "Wird verwendet, wenn ein Projekt kein eigenes SDK festlegt.": "Used when a project sets no SDK of its own.",
  "Steuert --release, Maven Compiler und die Gradle Toolchain.": "Drives --release, the Maven compiler and the Gradle toolchain.",
  "Encoding für Javac und neue Projektdateien.": "Encoding for javac and for new project files.",
  "Werden beim Plain-Java-Build an Javac übergeben.": "Passed to javac on a plain Java build.",
  "Aktiviert generierten Code aus MapStruct, Dagger und weiteren Prozessoren.": "Enables generated code from MapStruct, Dagger and other processors.",
  "Startet JDT LS automatisch mit einem lokal gefundenen Lombok-Agenten.": "Starts JDT LS with a Lombok agent found on this machine.",
  "Bezieht vom Build-Werkzeug registrierte generierte Quellordner in Navigation und Completion ein.": "Includes generated source folders registered by the build tool in navigation and completion.",
