  "Ausdrücke mit .if, .not, .for, .return oder .sout umformen.": "Transformar expresiones con .if, .not, .for, .return o .sout.",
  "Bestimme, welche Arten im Completion-Fenster erscheinen.": "Decide qué tipos aparecen en la ventana de autocompletado.",
  "Färbt Workbench und Editor gemeinsam ein.": "Colorea a la vez el banco de trabajo y el editor.",
  "Hebt oder senkt die Helligkeit des gewählten Themes und zieht es leicht zur Akzentfarbe. Die Schrift wandert dabei gegenläufig, damit der Kontrast erhalten bleibt.": "Sube o baja el brillo del tema elegido y lo acerca ligeramente al color de acento. El texto se mueve en sentido contrario, para que el contraste se mantenga.",
  "Sprache der Oberfläche. Nicht übersetzte Texte bleiben auf Deutsch.": "Idioma de la interfaz. Los textos aún sin traducir aparecen en inglés.",
  "Syntaxfarben des Editors, unabhängig vom gewählten Theme. Einzelne Farben lassen sich darunter überschreiben.": "Colores de sintaxis del editor, independientes del tema elegido. Cada color puede redefinirse más abajo.",
  "Skaliert die gesamte Workbench unabhängig von der Editor-Schrift.": "Escala todo el banco de trabajo con independencia de la fuente del editor.",
  "Abstände und Höhen für kleine oder große Displays.": "Espacios y alturas para pantallas pequeñas o grandes.",
  "Wie rund Fenster, Knöpfe und Felder sind. 0 % ist kantig, 200 % deutlich runder als die Vorgabe.": "Cuán redondeados son las ventanas, los botones y los campos. El 0 % es anguloso; el 200 %, bastante más redondo que lo predeterminado.",
  "Farbe für aktive Tabs, Fokus und primäre Aktionen.": "Color de las pestañas activas, del foco y de las acciones principales.",
  "Legt ein lokales Bild mittig als Layer hinter Editor und Toolfenster. Das Bild bleibt auf diesem PC.": "Coloca una imagen local detrás del editor y de las ventanas de herramientas. La imagen se queda en este PC.",
  "0 % blendet das Bild aus, 100 % zeigt es ohne zusätzliche Abschwächung.": "El 0 % oculta la imagen, el 100 % la muestra sin atenuación adicional.",
  "Welcome wird ausschließlich angezeigt, wenn kein Projekt aktiv ist.": "La pantalla de bienvenida solo aparece cuando no hay ningún proyecto activo.",
  "Deaktiviert Übergänge und laufende Dekorationen für eine ruhigere Oberfläche.": "Desactiva las transiciones y las decoraciones animadas, para una interfaz más serena.",
