  "Offene Dateien beim nächsten Start erneut öffnen.": "Volver a abrir en el próximo inicio los archivos que estaban abiertos.",
  "Größe der Datei- und Ordnersymbole.": "Tamaño de los iconos de archivo y de carpeta.",
  "Abstand zwischen den Ebenen des Projektbaums.": "Espacio entre los niveles del árbol del proyecto.",
  "Bestimme, welche Aktionen in der kompakten Toolbar sichtbar sind.": "Decide qué acciones son visibles en la barra de herramientas compacta.",
  "Nur Artefakte aus dem lokalen Maven-Cache verwenden.": "Usar únicamente los artefactos de la caché local de Maven.",
  "Keine Netzwerkzugriffe während Gradle-Builds.": "Sin acceso a la red durante las compilaciones de Gradle.",
