  "Automatisch erkannte Projektdefinition.": "Definición del proyecto detectada automáticamente.",
  "Packages betont Java-Strukturen, Ordner zeigt den Dateibaum unverändert.": "Paquetes resalta la estructura Java; Carpetas muestra el árbol de archivos tal cual.",
  "de › game › server kompakt als de.game.server darstellen.": "Mostrar de › game › server de forma compacta: de.game.server.",
  "Beim Zuklappen eines Projekts auch alle geöffneten Ordner und Module darin schließen.": "Al plegar un proyecto, cerrar también todas las carpetas y módulos abiertos dentro de él.",
  "Punkt-Ordner wie .git, .kiwi, .gradle und .idea nicht im Explorer anzeigen.": "Mantener fuera del explorador las carpetas que empiezan por punto, como .git, .kiwi, .gradle e .idea.",
  "target, build und out im Explorer verbergen.": "Ocultar target, build y out en el explorador.",
  "generated-sources und ähnliche Verzeichnisse verbergen.": "Ocultar generated-sources y directorios similares.",
  "Kommagetrennte Verzeichnisnamen im Explorer ausblenden.": "Nombres de directorio separados por comas que se ocultan en el explorador.",
  "Einfacher oder doppelter Klick auf Dateien.": "Un clic o doble clic sobre los archivos.",
  "Geöffnete Ordner und Auswahl lokal merken.": "Recordar localmente las carpetas abiertas y la selección.",
  "Run-, Test- und Debug-Ausgabe beim Start sichtbar machen.": "Mostrar la salida de ejecución, pruebas y depuración en cuanto arranca.",
  "Lokale Werte direkt neben der aktuellen Codezeile anzeigen.": "Mostrar los valores locales junto a la línea de código a la que pertenecen.",
  "Ersetzt normalen Methodencode sofort. Änderungen an bereits ausgeführtem Start- oder Initialisierungscode laden eine von Kiwi gestartete Anwendung automatisch neu; Breakpoints bleiben erhalten.": "Sustituye de inmediato el cuerpo de los métodos corrientes. Un cambio en el código de arranque o inicialización ya ejecutado recarga la aplicación que lanzó Kiwi; los puntos de interrupción se conservan.",
  "Debugger bei geworfenen Exceptions anhalten.": "Detener el depurador en las excepciones lanzadas.",
  "Wird Run-Konfigurationen als Standard hinzugefügt; Format NAME=WERT;PORT=8080.": "Se añade a las configuraciones de ejecución como valor predeterminado; formato NOMBRE=VALOR;PORT=8080.",
  "Ausgabe bei einem neuen Lauf nicht automatisch leeren.": "No vaciar automáticamente la salida en una ejecución nueva.",
  "Konfigurationen können bereits gruppiert und als Favorit markiert werden.": "Las configuraciones ya se pueden agrupar y marcar como favoritas.",
  "Wählt vertraute zusätzliche Tastenkürzel; Kiwi-Kürzel bleiben als Fallback aktiv.": "Añade un segundo juego de atajos que te resultará familiar; los de Kiwi siguen activos como respaldo.",
  "Feld anklicken und die gewünschte Tastenkombination drücken. Entf löscht die Belegung, Esc bricht ab.": "Haz clic en el campo y pulsa la combinación que quieras. Supr borra la asignación, Esc cancela.",
  "Schriftgröße des integrierten PowerShell-Terminals.": "Tamaño de fuente del terminal PowerShell integrado.",
  "JDT-Vorschläge jederzeit explizit öffnen.": "Abrir explícitamente las sugerencias de JDT en cualquier momento.",
  "Verfügbare Korrekturen und Refactorings öffnen.": "Abrir las correcciones y refactorizaciones disponibles.",
  "Symbol projektweit umbenennen.": "Renombrar un símbolo en todo el proyecto.",
  "Prüft beim Start das HTTPS-Manifest und installiert verifizierte Updates automatisch. Reine Oberflächen-Updates werden im laufenden Programm übernommen; nur wenn sich Kiwi selbst ändert, wird still installiert und der Workspace samt Tabs wieder geöffnet.": "Comprueba el manifiesto HTTPS al iniciar e instala las actualizaciones verificadas. Una actualización solo de la interfaz se aplica con el programa en marcha; únicamente si cambia Kiwi mismo se instala en silencio y se vuelve a abrir el espacio de trabajo con sus pestañas.",
  "Zuletzt geöffnetes Projekt wiederherstellen oder immer mit der Projektliste beginnen.": "Restaurar el último proyecto abierto o empezar siempre por la lista de proyectos.",
  "Bewertung automatischer Vorschläge. Ctrl+Space und Ctrl+Shift+Space setzen sie jederzeit außer Kraft.": "Cómo se ordenan las sugerencias automáticas. Ctrl+Espacio y Ctrl+Mayús+Espacio lo anulan en cualquier momento.",
  "Schaltet die Browser-Anmeldung frei. Lege dazu unter github.com/settings/developers eine OAuth-App mit aktiviertem Device Flow an. Ohne Client-ID bleibt die Anmeldung per Token.": "Habilita el inicio de sesión por el navegador. Crea para ello una aplicación OAuth con el device flow activado en github.com/settings/developers. Sin ID de cliente, queda el inicio de sesión con token.",
  "Stable erhält reguläre Versionen, Beta zusätzlich Vorabversionen.": "Stable recibe las versiones regulares; Beta, además, las preliminares.",
  "HTTPS-Adresse des Release-Manifests. Leer deaktiviert die Prüfung.": "Dirección HTTPS del manifiesto de versión. Vacío desactiva la comprobación.",
  "Der Download wird per SHA-256 geprüft. Betrifft das Update nur die Oberfläche, übernimmt Kiwi es ohne Neustart; sonst wird die Sitzung gesichert, still installiert und ohne manuelles Zutun wieder geöffnet.": "La descarga se verifica con SHA-256. Si la actualización afecta solo a la interfaz, Kiwi la aplica sin reiniciar; si no, la sesión se guarda, se instala en silencio y se vuelve a abrir sin que tengas que hacer nada.",
  "Speichert Absturzdetails nur nach Zustimmung lokal im Kiwi-Benutzerdatenordner. Es erfolgt kein automatischer Upload.": "Guarda los detalles de los fallos localmente en la carpeta de datos de usuario de Kiwi, y solo con tu consentimiento. No se envía nada.",
