  "Öffne ein bestehendes Projekt oder wähle eine Sprache im Projektassistenten.": "Откройте существующий проект или выберите язык в мастере проектов.",
  "Sprachen & Sprachserver": "Языки и языковые серверы",
  "Syntaxfarben, Schlüsselwörter, Vorlagen und Vorschläge aus geöffneten Dateien sind ohne Installation verfügbar. Sprachserver ergänzen typabhängige Autovervollständigung, Diagnosen und Navigation.": "Подсветка синтаксиса, ключевые слова, шаблоны и предложения из открытых файлов доступны без установки. Языковые серверы добавляют автодополнение типов, диагностику и навигацию.",
  "Java verwendet weiterhin JDT LS. HTML, CSS, JavaScript und TypeScript verwenden die integrierten Sprachdienste.": "Java продолжает использовать JDT LS. HTML, CSS, JavaScript и TypeScript используют встроенные языковые службы.",
  "Leerer Programmpfad bedeutet automatische Erkennung. Änderungen werden mit Übernehmen aktiviert. Compiler und Laufzeiten werden getrennt installiert.": "Пустой путь означает автоматическое обнаружение. Изменения активируются кнопкой «Применить». Компиляторы и среды выполнения устанавливаются отдельно.",
