  "Sticky Scroll": "Липкая прокрутка",
  "Aktuelle Zeile hervorheben": "Подсвечивать текущую строку",
  "Die Zeile, in der der Cursor steht, einfärben.": "Закрашивать строку, в которой стоит курсор.",
  "Breadcrumbs": "Навигационная цепочка",
  "Bracket Pair Colorization": "Раскраска парных скобок",
