  "Organize Imports on Save": "Упорядочивать импорты при сохранении",
  "Auto Save": "Автосохранение",
  "Fehlgeschlagene Tests erneut ausführen": "Повторить упавшие тесты",
  "Completion automatisch öffnen": "Открывать автодополнение автоматически",
  "Öffnungsverzögerung": "Задержка открытия",
  "Auto-Imports übernehmen": "Применять автоимпорты",
  "Dokumentation anzeigen": "Показывать документацию",
  "Häufig gewählte Vorschläge priorisieren": "Отдавать предпочтение часто выбираемым подсказкам",
  "Live Templates": "Живые шаблоны",
  "Postfix Templates": "Постфиксные шаблоны",
  "Namen eingeben oder groupId:artifactId:version einfügen.": "Введите название или вставьте groupId:artifactId:version.",
  "Einen Treffer auswählen — oder die vollständige Koordinate einfügen.": "Выберите результат — или вставьте полные координаты.",
  "Abhängigkeit hinzufügen…": "Добавить зависимость…",
  "Wird eingetragen in": "Будет добавлено в",
  "wurde installiert und als globale Laufzeit gewählt. Mit „Übernehmen“ speichern.": "установлен и выбран как глобальная среда выполнения. Сохраните кнопкой «Применить».",
  "war bereits vorhanden und ist jetzt gewählt. Mit „Übernehmen“ speichern.": "уже был установлен и теперь выбран. Сохраните кнопкой «Применить».",
  "Auf mvnrepository.com ansehen": "Открыть на mvnrepository.com",
  "Oberfläche": "Интерфейс",
  "ohne Neustart aktualisiert": "обновлён без перезапуска",
  "Kopiert": "Скопировано",
  "Versionsangaben kopieren": "Скопировать сведения о версии",
  "Welche Kiwi-Version läuft, worauf sie aufsetzt und was in einen Fehlerbericht gehört.": "Какая версия Kiwi работает, на чём она основана и что следует указать в отчёте об ошибке.",
  "Anweisungen fertigstellen": "Завершать инструкции",
  "new ArrayList wird zu new ArrayList<>(), und Enter setzt am Ende einer vollständigen Zeile das fehlende Semikolon.": "new ArrayList превращается в new ArrayList<>(), а Enter добавляет недостающую точку с запятой в конце завершённой строки.",
  "Methoden der offenen Datei": "Методы открытого файла",
  "Methoden und Felder aus der Datei selbst vorschlagen, auch bevor der Sprachserver sie gesehen hat, und beim Schreiben einer Deklaration passende Methodennamen anbieten.": "Предлагать методы и поля из самого файла, даже до того как их увидел языковой сервер, и подсказывать подходящие имена методов при написании объявления.",
  "Vorschlagsarten": "Виды подсказок",
  "Theme nachjustieren": "Подстроить тему",
