  "Symbol projektweit umbenennen.": "Een symbool in het hele project hernoemen.",
  "Prüft beim Start das HTTPS-Manifest und installiert verifizierte Updates automatisch. Reine Oberflächen-Updates werden im laufenden Programm übernommen; nur wenn sich Kiwi selbst ändert, wird still installiert und der Workspace samt Tabs wieder geöffnet.": "Controleert bij het starten het HTTPS-manifest en installeert geverifieerde updates. Een update van alleen de interface wordt tijdens het draaien toegepast; alleen wanneer Kiwi zelf verandert, wordt er stil geïnstalleerd en gaat de werkruimte met haar tabbladen weer open.",
  "Zuletzt geöffnetes Projekt wiederherstellen oder immer mit der Projektliste beginnen.": "Het laatst geopende project herstellen of altijd met de projectlijst beginnen.",
