  "Schaltet die Browser-Anmeldung frei. Lege dazu unter github.com/settings/developers eine OAuth-App mit aktiviertem Device Flow an. Ohne Client-ID bleibt die Anmeldung per Token.": "Maakt aanmelden via de browser mogelijk. Maak daarvoor op github.com/settings/developers een OAuth-app met device flow aan. Zonder client-ID blijft aanmelden met een token.",
