  "Automatisch erkannte Projektdefinition.": "Automatycznie wykryta definicja projektu.",
  "Packages betont Java-Strukturen, Ordner zeigt den Dateibaum unverändert.": "Pakiety podkreślają strukturę Javy, Foldery pokazują drzewo plików bez zmian.",
  "de › game › server kompakt als de.game.server darstellen.": "Pokazuj de › game › server zwięźle jako de.game.server.",
  "Beim Zuklappen eines Projekts auch alle geöffneten Ordner und Module darin schließen.": "Przy zwijaniu projektu zamykaj też wszystkie otwarte w nim foldery i moduły.",
  "Punkt-Ordner wie .git, .kiwi, .gradle und .idea nicht im Explorer anzeigen.": "Nie pokazuj w eksploratorze folderów zaczynających się od kropki, takich jak .git, .kiwi, .gradle i .idea.",
  "target, build und out im Explorer verbergen.": "Ukryj target, build i out w eksploratorze.",
  "generated-sources und ähnliche Verzeichnisse verbergen.": "Ukryj generated-sources i podobne katalogi.",
  "Kommagetrennte Verzeichnisnamen im Explorer ausblenden.": "Nazwy katalogów oddzielone przecinkami, ukrywane w eksploratorze.",
  "Einfacher oder doppelter Klick auf Dateien.": "Pojedyncze lub podwójne kliknięcie plików.",
  "Geöffnete Ordner und Auswahl lokal merken.": "Zapamiętuj lokalnie otwarte foldery i zaznaczenie.",
  "Run-, Test- und Debug-Ausgabe beim Start sichtbar machen.": "Pokazuj wyjście uruchamiania, testów i debugowania od razu po starcie.",
  "Lokale Werte direkt neben der aktuellen Codezeile anzeigen.": "Pokazuj wartości lokalne obok wiersza kodu, do którego należą.",
  "Ersetzt normalen Methodencode sofort. Änderungen an bereits ausgeführtem Start- oder Initialisierungscode laden eine von Kiwi gestartete Anwendung automatisch neu; Breakpoints bleiben erhalten.": "Zastępuje treść zwykłych metod od razu. Zmiana w już wykonanym kodzie startowym lub inicjalizacyjnym przeładowuje aplikację uruchomioną przez Kiwi; punkty przerwania pozostają.",
  "Debugger bei geworfenen Exceptions anhalten.": "Zatrzymuj debuger przy rzuconych wyjątkach.",
  "Wird Run-Konfigurationen als Standard hinzugefügt; Format NAME=WERT;PORT=8080.": "Dodawane do konfiguracji uruchamiania jako wartość domyślna; format NAZWA=WARTOŚĆ;PORT=8080.",
  "Ausgabe bei einem neuen Lauf nicht automatisch leeren.": "Nie czyść wyjścia automatycznie przy nowym uruchomieniu.",
  "Konfigurationen können bereits gruppiert und als Favorit markiert werden.": "Konfiguracje można już grupować i oznaczać jako ulubione.",
  "Wählt vertraute zusätzliche Tastenkürzel; Kiwi-Kürzel bleiben als Fallback aktiv.": "Dodaje znajomy drugi zestaw skrótów; skróty Kiwi pozostają jako zapasowe.",
  "Feld anklicken und die gewünschte Tastenkombination drücken. Entf löscht die Belegung, Esc bricht ab.": "Kliknij pole i naciśnij żądaną kombinację klawiszy. Del czyści przypisanie, Esc przerywa.",
  "Schriftgröße des integrierten PowerShell-Terminals.": "Rozmiar czcionki wbudowanego terminala PowerShell.",
  "JDT-Vorschläge jederzeit explizit öffnen.": "Otwieraj podpowiedzi JDT wprost w dowolnej chwili.",
  "Verfügbare Korrekturen und Refactorings öffnen.": "Otwórz dostępne poprawki i refaktoryzacje.",
  "Symbol projektweit umbenennen.": "Zmień nazwę symbolu w całym projekcie.",
  "Prüft beim Start das HTTPS-Manifest und installiert verifizierte Updates automatisch. Reine Oberflächen-Updates werden im laufenden Programm übernommen; nur wenn sich Kiwi selbst ändert, wird still installiert und der Workspace samt Tabs wieder geöffnet.": "Przy starcie sprawdza manifest HTTPS i instaluje zweryfikowane aktualizacje. Aktualizacja samego interfejsu jest stosowana podczas pracy; tylko gdy zmienia się samo Kiwi, instalacja przebiega po cichu, a obszar roboczy wraz z kartami zostaje otwarty ponownie.",
  "Zuletzt geöffnetes Projekt wiederherstellen oder immer mit der Projektliste beginnen.": "Przywracaj ostatnio otwarty projekt albo zawsze zaczynaj od listy projektów.",
  "Bewertung automatischer Vorschläge. Ctrl+Space und Ctrl+Shift+Space setzen sie jederzeit außer Kraft.": "Sposób porządkowania automatycznych podpowiedzi. Ctrl+spacja i Ctrl+Shift+spacja zawsze go pomijają.",
  "Schaltet die Browser-Anmeldung frei. Lege dazu unter github.com/settings/developers eine OAuth-App mit aktiviertem Device Flow an. Ohne Client-ID bleibt die Anmeldung per Token.": "Odblokowuje logowanie przez przeglądarkę. Utwórz w tym celu na github.com/settings/developers aplikację OAuth z włączonym device flow. Bez identyfikatora klienta pozostaje logowanie tokenem.",
  "Stable erhält reguläre Versionen, Beta zusätzlich Vorabversionen.": "Stable dostaje wydania zwykłe, Beta dodatkowo wstępne.",
  "HTTPS-Adresse des Release-Manifests. Leer deaktiviert die Prüfung.": "Adres HTTPS manifestu wydania. Puste wyłącza sprawdzanie.",
  "Der Download wird per SHA-256 geprüft. Betrifft das Update nur die Oberfläche, übernimmt Kiwi es ohne Neustart; sonst wird die Sitzung gesichert, still installiert und ohne manuelles Zutun wieder geöffnet.": "Pobrany plik jest sprawdzany sumą SHA-256. Jeśli aktualizacja dotyczy tylko interfejsu, Kiwi stosuje ją bez ponownego uruchomienia; w przeciwnym razie sesja zostaje zapisana, instalacja przebiega po cichu i wszystko otwiera się z powrotem bez twojego udziału.",
  "Speichert Absturzdetails nur nach Zustimmung lokal im Kiwi-Benutzerdatenordner. Es erfolgt kein automatischer Upload.": "Zapisuje szczegóły awarii lokalnie, w folderze danych użytkownika Kiwi, i tylko za zgodą. Nic nie jest wysyłane.",
