  "Färbt Workbench und Editor gemeinsam ein.": "Colore a bancada e o editor juntos.",
  "Hebt oder senkt die Helligkeit des gewählten Themes und zieht es leicht zur Akzentfarbe. Die Schrift wandert dabei gegenläufig, damit der Kontrast erhalten bleibt.": "Aumenta ou diminui o brilho do tema escolhido e o puxa de leve para a cor de destaque. O texto anda no sentido contrário, para que o contraste se mantenha.",
  "Sprache der Oberfläche. Nicht übersetzte Texte bleiben auf Deutsch.": "Idioma da interface. Os textos ainda não traduzidos aparecem em inglês.",
  "Syntaxfarben des Editors, unabhängig vom gewählten Theme. Einzelne Farben lassen sich darunter überschreiben.": "Cores de sintaxe do editor, independentes do tema escolhido. Cada cor pode ser redefinida abaixo.",
  "Skaliert die gesamte Workbench unabhängig von der Editor-Schrift.": "Redimensiona toda a bancada independentemente da fonte do editor.",
  "Abstände und Höhen für kleine oder große Displays.": "Espaços e alturas para telas pequenas ou grandes.",
  "Wie rund Fenster, Knöpfe und Felder sind. 0 % ist kantig, 200 % deutlich runder als die Vorgabe.": "O quanto janelas, botões e campos são arredondados. 0 % é anguloso; 200 %, bem mais redondo que o padrão.",
  "Farbe für aktive Tabs, Fokus und primäre Aktionen.": "Cor das abas ativas, do foco e das ações principais.",
  "Legt ein lokales Bild mittig als Layer hinter Editor und Toolfenster. Das Bild bleibt auf diesem PC.": "Coloca uma imagem local atrás do editor e das janelas de ferramentas. A imagem fica neste computador.",
  "0 % blendet das Bild aus, 100 % zeigt es ohne zusätzliche Abschwächung.": "0 % esconde a imagem, 100 % a mostra sem nenhum atenuamento a mais.",
  "Welcome wird ausschließlich angezeigt, wenn kein Projekt aktiv ist.": "A tela de boas-vindas só aparece enquanto nenhum projeto está ativo.",
  "Deaktiviert Übergänge und laufende Dekorationen für eine ruhigere Oberfläche.": "Desliga transições e enfeites em movimento, para uma interface mais calma.",
  "Parameternamen und Typinformationen durch JDT LS anzeigen.": "Mostrar os nomes dos parâmetros e as informações de tipo vindas do JDT LS.",
  "Offene Dateien beim nächsten Start erneut öffnen.": "Na próxima inicialização, reabrir os arquivos que estavam abertos.",
  "Größe der Datei- und Ordnersymbole.": "Tamanho dos ícones de arquivos e pastas.",
  "Abstand zwischen den Ebenen des Projektbaums.": "Espaço entre os níveis da árvore do projeto.",
