  "Gradle --parallel beziehungsweise Maven -T 1C verwenden.": "Usar Gradle --parallel e Maven -T 1C.",
  "Entfernt bei Maven veraltete Testklassen, bevor die Tests neu kompiliert werden.": "Remove as classes de teste desatualizadas do Maven antes de recompilar os testes.",
  "Kompilieren und starten mit --enable-preview.": "Compilar e executar com --enable-preview.",
  "Kommagetrennte Ordner werden nicht von JDT LS importiert.": "Pastas separadas por vírgulas que o JDT LS não vai importar.",
  "Workspace-relative JAR-Pfade nicht indexieren.": "Não indexar estes caminhos de JAR relativos ao espaço de trabalho.",
  "Automatisch erkannte Projektdefinition.": "Definição do projeto detectada automaticamente.",
  "Packages betont Java-Strukturen, Ordner zeigt den Dateibaum unverändert.": "Pacotes realça a estrutura Java; Pastas mostra a árvore de arquivos como ela é.",
  "de › game › server kompakt als de.game.server darstellen.": "Mostrar de › game › server de forma compacta: de.game.server.",
  "Beim Zuklappen eines Projekts auch alle geöffneten Ordner und Module darin schließen.": "Ao recolher um projeto, fechar também todas as pastas e módulos abertos dentro dele.",
  "Punkt-Ordner wie .git, .kiwi, .gradle und .idea nicht im Explorer anzeigen.": "Manter fora do explorador as pastas que começam com ponto, como .git, .kiwi, .gradle e .idea.",
  "target, build und out im Explorer verbergen.": "Ocultar target, build e out no explorador.",
  "generated-sources und ähnliche Verzeichnisse verbergen.": "Ocultar generated-sources e diretórios semelhantes.",
  "Kommagetrennte Verzeichnisnamen im Explorer ausblenden.": "Nomes de diretórios separados por vírgulas a ocultar no explorador.",
  "Einfacher oder doppelter Klick auf Dateien.": "Um ou dois cliques nos arquivos.",
  "Geöffnete Ordner und Auswahl lokal merken.": "Lembrar localmente as pastas abertas e a seleção.",
  "Run-, Test- und Debug-Ausgabe beim Start sichtbar machen.": "Mostrar a saída de execução, testes e depuração assim que começa.",
  "Lokale Werte direkt neben der aktuellen Codezeile anzeigen.": "Mostrar os valores locais ao lado da linha de código a que pertencem.",
  "Ersetzt normalen Methodencode sofort. Änderungen an bereits ausgeführtem Start- oder Initialisierungscode laden eine von Kiwi gestartete Anwendung automatisch neu; Breakpoints bleiben erhalten.": "Substitui na hora o corpo dos métodos comuns. Uma mudança no código de inicialização já executado recarrega a aplicação que o Kiwi iniciou; os pontos de parada permanecem.",
  "Debugger bei geworfenen Exceptions anhalten.": "Parar o depurador nas exceções lançadas.",
  "Wird Run-Konfigurationen als Standard hinzugefügt; Format NAME=WERT;PORT=8080.": "É adicionado às configurações de execução como padrão; formato NOME=VALOR;PORT=8080.",
  "Ausgabe bei einem neuen Lauf nicht automatisch leeren.": "Não limpar a saída automaticamente a cada nova execução.",
  "Konfigurationen können bereits gruppiert und als Favorit markiert werden.": "As configurações já podem ser agrupadas e marcadas como favoritas.",
  "Wählt vertraute zusätzliche Tastenkürzel; Kiwi-Kürzel bleiben als Fallback aktiv.": "Acrescenta um segundo conjunto de atalhos familiar; os do Kiwi continuam como reserva.",
  "Feld anklicken und die gewünschte Tastenkombination drücken. Entf löscht die Belegung, Esc bricht ab.": "Clique no campo e pressione a combinação desejada. Del apaga a atribuição, Esc cancela.",
  "Schriftgröße des integrierten PowerShell-Terminals.": "Tamanho da fonte do terminal PowerShell embutido.",
  "JDT-Vorschläge jederzeit explizit öffnen.": "Abrir as sugestões do JDT explicitamente a qualquer momento.",
  "Verfügbare Korrekturen und Refactorings öffnen.": "Abrir as correções e refatorações disponíveis.",
  "Symbol projektweit umbenennen.": "Renomear um símbolo em todo o projeto.",
  "Prüft beim Start das HTTPS-Manifest und installiert verifizierte Updates automatisch. Reine Oberflächen-Updates werden im laufenden Programm übernommen; nur wenn sich Kiwi selbst ändert, wird still installiert und der Workspace samt Tabs wieder geöffnet.": "Ao iniciar, verifica o manifesto HTTPS e instala as atualizações verificadas. Uma atualização só da interface é aplicada com o programa em funcionamento; apenas quando o próprio Kiwi muda é que a instalação ocorre em silêncio e o espaço de trabalho volta a abrir com suas abas.",
  "Zuletzt geöffnetes Projekt wiederherstellen oder immer mit der Projektliste beginnen.": "Restaurar o último projeto aberto ou começar sempre pela lista de projetos.",
  "Bewertung automatischer Vorschläge. Ctrl+Space und Ctrl+Shift+Space setzen sie jederzeit außer Kraft.": "Como as sugestões automáticas são ordenadas. Ctrl+espaço e Ctrl+Shift+espaço passam por cima disso a qualquer momento.",
  "Schaltet die Browser-Anmeldung frei. Lege dazu unter github.com/settings/developers eine OAuth-App mit aktiviertem Device Flow an. Ohne Client-ID bleibt die Anmeldung per Token.": "Libera a entrada pelo navegador. Crie para isso um aplicativo OAuth com device flow ativado em github.com/settings/developers. Sem ID de cliente, resta a entrada por token.",
