  "Java-Dateien beim Speichern formatieren.": "A Java fájlok formázása mentéskor.",
  "Entfernt unbenutzte Imports und übernimmt die JDT-Importreihenfolge.": "Eltávolítja a nem használt importokat, és a JDT sorrendjét veszi át.",
  "Änderungen nach kurzer Verzögerung speichern.": "A változtatások mentése rövid késleltetés után.",
  "Bietet nach einem Testlauf einen direkten Rerun der fehlgeschlagenen Tests an.": "Egy tesztkör után felajánlja a megbukott tesztek azonnali újrafuttatását.",
  "Vorschläge beim Tippen und an Trigger-Zeichen anzeigen.": "Javaslatok megjelenítése gépelés közben és a kiváltó karaktereknél.",
  "Wartezeit vor automatischen Vorschlägen. Strg+Leertaste öffnet immer sofort.": "Várakozás, mielőtt a javaslatok maguktól megjelennének. A Ctrl+szóköz mindig azonnal megnyitja őket.",
  "Completion-Treffer strikt nach Schreibweise filtern.": "A kiegészítési találatok szűrése szigorúan a kis- és nagybetűk szerint.",
