  "Vorlagen wie psvm, sout, iter und try anbieten.": "Sablonok felkínálása, mint a psvm, sout, iter és try.",
  "Ausdrücke mit .if, .not, .for, .return oder .sout umformen.": "Kifejezések átalakítása a .if, .not, .for, .return vagy .sout utótaggal.",
  "Bestimme, welche Arten im Completion-Fenster erscheinen.": "Döntsd el, milyen fajták jelenjenek meg a kiegészítés ablakában.",
  "Färbt Workbench und Editor gemeinsam ein.": "A munkapadot és a szerkesztőt együtt színezi.",
  "Hebt oder senkt die Helligkeit des gewählten Themes und zieht es leicht zur Akzentfarbe. Die Schrift wandert dabei gegenläufig, damit der Kontrast erhalten bleibt.": "Növeli vagy csökkenti a választott téma fényerejét, és kissé a kiemelőszín felé húzza. A szöveg közben az ellenkező irányba mozdul, hogy a kontraszt megmaradjon.",
  "Sprache der Oberfläche. Nicht übersetzte Texte bleiben auf Deutsch.": "A felület nyelve. A még le nem fordított szövegek angolul jelennek meg.",
  "Syntaxfarben des Editors, unabhängig vom gewählten Theme. Einzelne Farben lassen sich darunter überschreiben.": "A szerkesztő szintaxisszínei, a választott témától függetlenül. Az egyes színek alább felülírhatók.",
  "Skaliert die gesamte Workbench unabhängig von der Editor-Schrift.": "Az egész munkapadot a szerkesztő betűtípusától függetlenül méretezi.",
  "Abstände und Höhen für kleine oder große Displays.": "Térközök és magasságok kis vagy nagy képernyőkhöz.",
  "Wie rund Fenster, Knöpfe und Felder sind. 0 % ist kantig, 200 % deutlich runder als die Vorgabe.": "Mennyire kerekek az ablakok, gombok és mezők. A 0 % szögletes, a 200 % jóval kerekebb az alapértelmezettnél.",
  "Farbe für aktive Tabs, Fokus und primäre Aktionen.": "Az aktív lapok, a fókusz és az elsődleges műveletek színe.",
  "Legt ein lokales Bild mittig als Layer hinter Editor und Toolfenster. Das Bild bleibt auf diesem PC.": "Egy helyi képet helyez a szerkesztő és az eszközablakok mögé. A kép ezen a gépen marad.",
  "0 % blendet das Bild aus, 100 % zeigt es ohne zusätzliche Abschwächung.": "A 0 % elrejti a képet, a 100 % további halványítás nélkül mutatja.",
  "Welcome wird ausschließlich angezeigt, wenn kein Projekt aktiv ist.": "Az üdvözlőképernyő csak akkor jelenik meg, ha egyetlen projekt sem aktív.",
  "Deaktiviert Übergänge und laufende Dekorationen für eine ruhigere Oberfläche.": "Kikapcsolja az átmeneteket és a mozgó díszítéseket, hogy nyugodtabb legyen a felület.",
  "Parameternamen und Typinformationen durch JDT LS anzeigen.": "A JDT LS-től kapott paraméternevek és típusadatok megjelenítése.",
  "Offene Dateien beim nächsten Start erneut öffnen.": "A következő indításkor nyíljanak meg újra a nyitva volt fájlok.",
