  "Lokale Werte direkt neben der aktuellen Codezeile anzeigen.": "A helyi értékek megjelenítése amellett a kódsor mellett, amelyhez tartoznak.",
  "Ersetzt normalen Methodencode sofort. Änderungen an bereits ausgeführtem Start- oder Initialisierungscode laden eine von Kiwi gestartete Anwendung automatisch neu; Breakpoints bleiben erhalten.": "A szokásos metódustörzseket azonnal kicseréli. A már lefutott indító vagy inicializáló kód módosítása újratölti a Kiwi által indított alkalmazást; a töréspontok megmaradnak.",
  "Debugger bei geworfenen Exceptions anhalten.": "A hibakereső álljon meg a dobott kivételeknél.",
  "Wird Run-Konfigurationen als Standard hinzugefügt; Format NAME=WERT;PORT=8080.": "Alapértelmezésként kerül a futtatási beállításokba; alakja NÉV=ÉRTÉK;PORT=8080.",
  "Ausgabe bei einem neuen Lauf nicht automatisch leeren.": "Új futtatáskor ne törlődjön magától a kimenet.",
  "Konfigurationen können bereits gruppiert und als Favorit markiert werden.": "A beállítások már csoportosíthatók és kedvencnek jelölhetők.",
  "Wählt vertraute zusätzliche Tastenkürzel; Kiwi-Kürzel bleiben als Fallback aktiv.": "Egy megszokott, második gyorsbillentyű-készletet ad hozzá; a Kiwi sajátjai tartalékként megmaradnak.",
  "Feld anklicken und die gewünschte Tastenkombination drücken. Entf löscht die Belegung, Esc bricht ab.": "Kattints a mezőbe, és nyomd le a kívánt billentyűkombinációt. A Del törli a hozzárendelést, az Esc megszakítja.",
  "Schriftgröße des integrierten PowerShell-Terminals.": "A beépített PowerShell terminál betűmérete.",
  "JDT-Vorschläge jederzeit explizit öffnen.": "A JDT javaslatainak kifejezett megnyitása bármikor.",
  "Verfügbare Korrekturen und Refactorings öffnen.": "Az elérhető javítások és átalakítások megnyitása.",
  "Symbol projektweit umbenennen.": "Szimbólum átnevezése az egész projektben.",
  "Prüft beim Start das HTTPS-Manifest und installiert verifizierte Updates automatisch. Reine Oberflächen-Updates werden im laufenden Programm übernommen; nur wenn sich Kiwi selbst ändert, wird still installiert und der Workspace samt Tabs wieder geöffnet.": "Indításkor ellenőrzi a HTTPS-leírót, és telepíti az ellenőrzött frissítéseket. A csak felületet érintő frissítés futó program mellett lép életbe; a telepítés csak akkor zajlik csendben, ha maga a Kiwi változik, és ilyenkor a munkaterület a lapjaival együtt újra megnyílik.",
  "Zuletzt geöffnetes Projekt wiederherstellen oder immer mit der Projektliste beginnen.": "A legutóbb megnyitott projekt visszaállítása, vagy mindig a projektlistával kezdés.",
  "Bewertung automatischer Vorschläge. Ctrl+Space und Ctrl+Shift+Space setzen sie jederzeit außer Kraft.": "Az automatikus javaslatok rangsorolása. A Ctrl+szóköz és a Ctrl+Shift+szóköz bármikor felülírja.",
  "Schaltet die Browser-Anmeldung frei. Lege dazu unter github.com/settings/developers eine OAuth-App mit aktiviertem Device Flow an. Ohne Client-ID bleibt die Anmeldung per Token.": "Engedélyezi a böngészőn keresztüli bejelentkezést. Hozz létre ehhez a github.com/settings/developers oldalon egy OAuth alkalmazást bekapcsolt device flow-val. Ügyfélazonosító nélkül marad a tokenes bejelentkezés.",
  "Stable erhält reguläre Versionen, Beta zusätzlich Vorabversionen.": "A Stable a rendes kiadásokat kapja, a Beta ezenfelül az előzeteseket is.",
  "HTTPS-Adresse des Release-Manifests. Leer deaktiviert die Prüfung.": "A kiadási leíró HTTPS-címe. Üresen hagyva az ellenőrzés kikapcsol.",
  "Der Download wird per SHA-256 geprüft. Betrifft das Update nur die Oberfläche, übernimmt Kiwi es ohne Neustart; sonst wird die Sitzung gesichert, still installiert und ohne manuelles Zutun wieder geöffnet.": "A letöltést SHA-256 ellenőrzi. Ha a frissítés csak a felületet érinti, a Kiwi újraindítás nélkül veszi át; egyébként menti a munkamenetet, csendben telepít, és minden magától nyílik meg újra.",
  "Speichert Absturzdetails nur nach Zustimmung lokal im Kiwi-Benutzerdatenordner. Es erfolgt kein automatischer Upload.": "Az összeomlások részleteit helyben, a Kiwi felhasználói adatmappájában tárolja, és csak hozzájárulással. Semmi sem kerül elküldésre.",
  "Aktiviert Electrons Barrierefreiheitsbaum dauerhaft und verbessert semantische Statusmeldungen.": "Tartósan bekapcsolva tartja az Electron akadálymentességi fáját, és javítja a felolvasott állapotüzeneteket.",
  "Hebt den Tastaturfokus in Menüs, Toolfenstern und Formularen stärker hervor.": "Erősebben kiemeli a billentyűzetfókuszt a menükben, eszközablakokban és űrlapokon.",
