const dictionaries: Record<Locale, Record<string, string>> = {
  de: {},
  en: english,
  fr: french,
  es: spanish,
  ru: russian,
  it: italian,
  nl: dutch,
  pl: polish,
  pt: portuguese,
  hu: hungarian,
  tr: turkish,
};

/**
 * What a language falls back to when it has no word for something.
 *
 * German is the source, so an untranslated text is German — which is the right
 * answer for an English reader who chose English over German, and the wrong one
 * for a Russian reader, who is unlikely to read either. The later languages
 * fall through English first, so a gap shows a language most people working in
 * this field can read rather than the source language by accident.
 */
const fallbacks: Record<Locale, Locale[]> = {
  de: [],
  en: [],
  fr: ["en"],
  es: ["en"],
  ru: ["en"],
  it: ["en"],
  nl: ["en"],
  pl: ["en"],
  pt: ["en"],
  hu: ["en"],
  tr: ["en"],
};

function lookup(locale: Locale, source: string): string {
  const direct = dictionaries[locale]?.[source];
  if (direct !== undefined) return direct;
  for (const next of fallbacks[locale] || []) {
    const value = dictionaries[next]?.[source];
    if (value !== undefined) return value;
  }
  return source;
}

export function createTranslator(locale: Locale) {
  const active = dictionaries[locale] ? locale : "de";
  /** Returns the localised text, or what the language falls back to. */
  return (source: string): string => lookup(active, source);
}

let activeLocale: Locale = "de";

/**
 * Sets the locale for the module-level `t`. Called during render so dialogs
 * that are not passed a translator still read the current language instead of
 * threading a prop through every component.
 */
export function setActiveLocale(locale: Locale) {
  activeLocale = dictionaries[locale] ? locale : "de";
}

/**
 * Whether a German source text has an entry for the given locale.
 *
 * `t` cannot answer this: a word that is spelled the same in both languages
 * returns unchanged whether it was translated or merely missing, and the test
 * that guards the coverage has to tell those two apart.
 */
export function hasTranslation(source: string, locale: Locale = "en"): boolean {
  return Object.prototype.hasOwnProperty.call(dictionaries[locale] || {}, source);
}

/**
 * The German texts a language has an entry for.
 *
 * Only the coverage tests need this. It is exported rather than reached for
 * through the module internals so those tests break loudly if the dictionaries
 * are ever restructured, instead of quietly measuring nothing.
 */
export function germanKeys(locale: Locale): string[] {
  return Object.keys(dictionaries[locale] || {});
}

/** Localised text, falling back to the German source. */
export function t(source: string): string {
  return lookup(activeLocale, source);
}

/** Locale for a fresh install, taken from the OS when it is one we ship. */
export function detectLocale(): Locale {
  const language = (globalThis.navigator?.language || "de").slice(0, 2).toLowerCase();
  return locales.some((entry) => entry.id === language) ? (language as Locale) : "de";
}
